import { useState } from 'react';
import { JxCalendar, JxButton } from '@jinx-ui/react';

function startOfDay(d: Date): Date {
  const copy = new Date(d);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

function daysAgo(n: number): Date {
  const d = startOfDay(new Date());
  d.setDate(d.getDate() - n);
  return d;
}

interface ReportDatePickerProps {
  onChange?: (value: Date | null) => void;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(null);

  const handleChange = (value: Date | null) => {
    setDate(value);
    onChange?.(value);
  };

  const quickOptions: { label: string; getValue: () => Date }[] = [
    { label: 'Сегодня', getValue: () => daysAgo(0) },
    { label: 'Вчера', getValue: () => daysAgo(1) },
    { label: 'Неделя назад', getValue: () => daysAgo(7) },
  ];

  const isActive = (value: Date) =>
    date != null && startOfDay(date).getTime() === value.getTime();

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '12px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        padding: '16px',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {quickOptions.map((option) => {
          const value = option.getValue();
          return (
            <JxButton
              key={option.label}
              type="button"
              size="sm"
              variant={isActive(value) ? 'primary' : 'outline'}
              onClick={() => handleChange(value)}
            >
              {option.label}
            </JxButton>
          );
        })}
      </div>
      <JxCalendar
        locale="ru-RU"
        value={date}
        onValueChange={handleChange}
      />
    </div>
  );
}

